// Preparation only: three read-only GETs, no generation and no routing writes.
import fs from 'node:fs';import {loadConfig} from '../src/config/index.js';
process.loadEnvFile('.env');const p=loadConfig().ai.providers.find(p=>p.id==='openrouter');
if(!p?.key||p.base!=='https://openrouter.ai/api/v1')throw Error('Existing official OpenRouter key/endpoint unavailable');
const out='docs/verification/openrouter-coding-preparation-20261107';fs.mkdirSync(out,{recursive:true});
const ids=['cohere/north-mini-code:free','nvidia/nemotron-3-ultra-550b-a55b:free','nvidia/nemotron-3.5-super-vl:free'],calls=[];
async function read(route,authenticated){const start=Date.now(),r=await fetch(p.base+route,{method:'GET',headers:authenticated?{Authorization:'Bearer '+p.key}:{},redirect:'error',signal:AbortSignal.timeout(15000)});calls.push({route,httpStatus:r.status,elapsedMs:Date.now()-start,retryAfter:r.headers.get('retry-after')});if(!r.ok)throw Error('Read-only '+route+' HTTP '+r.status+'; no retry');const reader=r.body.getReader(),chunks=[];let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>8000000){await reader.cancel();throw Error('Catalog exceeds bound');}chunks.push(value);}return JSON.parse(Buffer.concat(chunks).toString('utf8'));}
const all=await read('/models',false),user=await read('/models/user',true),account=await read('/key',true);
const zero=m=>!!m?.pricing&&m.pricing.prompt!==undefined&&m.pricing.completion!==undefined&&Object.values(m.pricing).every(v=>['string','number'].includes(typeof v)&&String(v).trim()!==''&&Number(v)===0);
const safe=m=>m?{id:m.id,pricing:m.pricing,allReportedPricesZero:zero(m),contextLength:m.context_length,maxOutput:m.top_provider?.max_completion_tokens??null,supportedParameters:m.supported_parameters||[],expirationDate:m.expiration_date??null}:null;
const candidates=ids.map(id=>{const a=all.data?.find(m=>m.id===id),b=user.data?.find(m=>m.id===id);return {id,public:safe(a),account:safe(b),eligible:!!a&&!!b&&zero(a)&&zero(b)};});
const selected=candidates.find(c=>c.id===ids[0]&&c.eligible&&c.account.supportedParameters.includes('max_tokens'));
const result={checkedAt:new Date().toISOString(),calls,keyAuthenticated:true,accountFreeTier:account.data?.is_free_tier??null,freeDailyRequests:account.data?.free_model_daily_requests??null,candidates,selectedModel:selected?.id??null,generationRequests:0,configurationChanged:false};
fs.writeFileSync(out+'/catalog-account-check.json',JSON.stringify(result,null,2));
if(selected){const body={model:selected.id,messages:[{role:'system',content:'Return concise JSON only with explanation, edgeCase, code, and tests (exactly two brief test suggestions). No Markdown fences, tools, or claims of executed tests.'},{role:'user',content:'Review function calculateTotal(prices) { return prices.reduce((sum, price) => sum + price, 0); } Explain it briefly, identify an invalid-input edge case, return a corrected function accepting only an array of finite numbers and rejecting invalid inputs, and suggest two meaningful tests.'}],stream:false,max_tokens:500,provider:{allow_fallbacks:false,max_price:{prompt:0,completion:0,request:0}}};fs.writeFileSync(out+'/inactive-proposed-request.json',JSON.stringify({active:false,authorization:'PENDING — no generation permitted',endpoint:p.base+'/chat/completions',timeoutMs:60000,maximumRequests:1,retries:0,body},null,2));}
console.log(JSON.stringify(result,null,2));
